import React, { useState } from 'react';
import Navbar from '../components/Navbar';
import { FaPlus, FaCheckCircle, FaCircle, FaTrash } from 'react-icons/fa';

function Habits() {
  const [habits, setHabits] = useState([
    { id: 1, name: 'Drink Water', target: '8 glasses', completed: false },
    { id: 2, name: 'Exercise', target: '30 mins', completed: false },
    { id: 3, name: 'Meditate', target: '10 mins', completed: false },
    { id: 4, name: 'Read Book', target: '20 pages', completed: false },
  ]);
  const [newHabit, setNewHabit] = useState('');

  const toggleHabit = (id) => {
    setHabits(habits.map(habit =>
      habit.id === id ? { ...habit, completed: !habit.completed } : habit
    ));
  };

  const addHabit = () => {
    if (newHabit.trim()) {
      setHabits([...habits, {
        id: Date.now(),
        name: newHabit,
        target: 'Daily',
        completed: false
      }]);
      setNewHabit('');
    }
  };

  const deleteHabit = (id) => {
    setHabits(habits.filter(habit => habit.id !== id));
  };

  const completedCount = habits.filter(h => h.completed).length;

  return (
    <div style={styles.container}>
      <Navbar />
      
      <div style={styles.content}>
        <div style={styles.header}>
          <h1 style={styles.title}>✅ Habit Tracker</h1>
          <p style={styles.subtitle}>Track your daily habits and build consistency</p>
        </div>

        <div style={styles.progressCard}>
          <div style={styles.progressInfo}>
            <span>Daily Progress</span>
            <span>{completedCount}/{habits.length} completed</span>
          </div>
          <div style={styles.progressBar}>
            <div style={{...styles.progressFill, width: `${(completedCount/habits.length)*100}%`}} />
          </div>
        </div>

        <div style={styles.addHabitCard}>
          <input
            type="text"
            placeholder="Add a new habit... (e.g., 'Walk 5000 steps')"
            style={styles.input}
            value={newHabit}
            onChange={(e) => setNewHabit(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && addHabit()}
          />
          <button onClick={addHabit} style={styles.addBtn}>
            <FaPlus /> Add Habit
          </button>
        </div>

        <div style={styles.habitsList}>
          {habits.map(habit => (
            <div key={habit.id} style={styles.habitItem}>
              <div style={styles.habitLeft}>
                <div onClick={() => toggleHabit(habit.id)} style={styles.checkbox}>
                  {habit.completed ? 
                    <FaCheckCircle color="#2ecc71" size={24} /> : 
                    <FaCircle color="#ccc" size={24} />
                  }
                </div>
                <div>
                  <h4 style={{...styles.habitName, textDecoration: habit.completed ? 'line-through' : 'none'}}>
                    {habit.name}
                  </h4>
                  <p style={styles.habitTarget}>🎯 {habit.target}</p>
                </div>
              </div>
              <button onClick={() => deleteHabit(habit.id)} style={styles.deleteBtn}>
                <FaTrash color="#e74c3c" />
              </button>
            </div>
          ))}
        </div>

        {habits.length === 0 && (
          <div style={styles.emptyState}>
            <p>✨ No habits yet. Add your first habit above! ✨</p>
          </div>
        )}
      </div>
    </div>
  );
}

const styles = {
  container: {
    minHeight: '100vh',
    background: '#f5f7fa',
  },
  content: {
    maxWidth: '600px',
    margin: '0 auto',
    padding: '20px',
    paddingTop: '80px',
  },
  header: {
    textAlign: 'center',
    marginBottom: '30px',
  },
  title: {
    fontSize: '32px',
    color: '#333',
  },
  subtitle: {
    color: '#666',
    marginTop: '5px',
  },
  progressCard: {
    background: 'white',
    borderRadius: '15px',
    padding: '20px',
    marginBottom: '20px',
  },
  progressInfo: {
    display: 'flex',
    justifyContent: 'space-between',
    marginBottom: '10px',
  },
  progressBar: {
    height: '10px',
    background: '#e0e0e0',
    borderRadius: '5px',
    overflow: 'hidden',
  },
  progressFill: {
    height: '100%',
    background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
    borderRadius: '5px',
    transition: 'width 0.3s ease',
  },
  addHabitCard: {
    background: 'white',
    borderRadius: '15px',
    padding: '20px',
    marginBottom: '20px',
    display: 'flex',
    gap: '10px',
  },
  input: {
    flex: 1,
    padding: '12px',
    border: '2px solid #e0e0e0',
    borderRadius: '10px',
    fontSize: '14px',
    outline: 'none',
  },
  addBtn: {
    padding: '12px 20px',
    background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
    color: 'white',
    border: 'none',
    borderRadius: '10px',
    cursor: 'pointer',
    display: 'flex',
    alignItems: 'center',
    gap: '8px',
  },
  habitsList: {
    display: 'flex',
    flexDirection: 'column',
    gap: '10px',
  },
  habitItem: {
    background: 'white',
    borderRadius: '15px',
    padding: '15px',
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
  },
  habitLeft: {
    display: 'flex',
    alignItems: 'center',
    gap: '15px',
  },
  checkbox: {
    cursor: 'pointer',
  },
  habitName: {
    fontSize: '16px',
    marginBottom: '4px',
  },
  habitTarget: {
    fontSize: '12px',
    color: '#666',
  },
  deleteBtn: {
    background: 'none',
    border: 'none',
    cursor: 'pointer',
  },
  emptyState: {
    textAlign: 'center',
    padding: '40px',
    color: '#666',
  },
};

export default Habits;
